import json,re
b=[json.loads(l) for l in open('/tmp/before.jsonl')]
a=[json.loads(l) for l in open('/tmp/after.jsonl')]
for i,(x,y) in enumerate(zip(b,a),1):
    if x==y: continue
    for k in x:
        if x[k]!=y.get(k):
            bs=str(x[k]); as_=str(y[k])
            # find all ch:trace marker segments in before and after
            MR=re.compile(r"ch:trace\s+row=[^\"'`]*",re.I)
            mb=MR.findall(bs); ma=MR.findall(as_)
            if len(mb)!=len(ma):
                print('MARKER COUNT CHANGE',i,x.get('id'),k,len(mb),len(ma))
            for m1,m2 in zip(mb,ma):
                if m1!=m2:
                    print(f'--- {i} {x.get("id")} [{k}]')
                    print('  B:',m1)
                    print('  A:',m2)
